style.css:
@-moz-document domain("roblox.com") {
html {
    background-color: #080f1c !important;
  }

  html body#rbx-body, html body {
    background: linear-gradient(rgba(3, 8, 18, .24), rgba(3, 8, 18, .24)),
      url("data:image/webp;base64,") center center / cover no-repeat fixed !important;
    color: #f2f5ff !important;
    min-height: 100vh !important;
  }

  #container-main, .container-main, .content, .content-container,
  #wrap {
    background: transparent !important;
  }

  .container-main {
    min-height: 100vh !important;
  }

  #header, .rbx-header, .navbar-fixed-top,
  #navigation, .rbx-left-col, .footer-container, #footer-container {
    background-color: rgba(8, 15, 28, .93) !important;
    background-image: none !important;
    color: #f2f5ff !important;
  }

  .section-content, .rbx-tab-content, .tab-content {
    background-color: rgba(8, 15, 28, .74) !important;
    background-image: none !important;
    color: #f2f5ff !important;
  }

  .game-card, .game-card-container, .item-card,
  .item-card-container, .game-card-info {
    background-color: transparent !important;
  }

  h1, h2, h3, h4, h5, h6, a,
  .text-default, .text-label, .text-name,
  .text-body, .text-description, .text-lead,
  .game-card-name, .game-card-info, .item-card-name, .friend-name {
    color: #f2f5ff !important;
  }

  .text-secondary, .text-date-hint, .text-footer {
    color: #c5d3e5 !important;
  }

  .input-field, .form-control, select, textarea,
  .navbar-search, .btn-secondary, .btn-control {
    background-color: #14243a !important;
    border-color: #3d638a !important;
    color: #f2f5ff !important;
  }

  input::placeholder, textarea::placeholder {
    color: #bbc9db !important;
    opacity: 1 !important;
  }

  .modal-content, .dropdown-menu, .popover {
    background-color: #101c2e !important;
    color: #f2f5ff !important;
  }
}
